//! Status effects and potion types with their data, in static tables generated by
//! `cargo xtask gen` from the dump, so nothing is built at start and a lookup never allocates.

mod table;

pub use table::{Potion, Type};

use crate::nbt::{Compound, Value};

/// The key of an instance's ambient flag in its saved form.
const AMBIENT: &str = "Ambient";

/// The key of an instance's amplifier in its saved form.
const AMPLIFIER: &str = "Amplifier";

/// The key of an instance's duration in its saved form.
const DURATION: &str = "Duration";

/// The key of an instance's effect ID in its saved form.
const ID: &str = "Id";

/// The saved duration of an infinite instance.
const INFINITE_DURATION: i32 = -1;

/// The longest duration an instance holds, in ticks (`i32::MAX`: the saved and sent
/// int).
pub const MAX_DURATION: u32 = i32::MAX.cast_unsigned();

/// The key of an instance's particle flag in its saved form.
const PARTICLES: &str = "ShowParticles";

/// The number of effect types ([`Type::all`]).
pub(crate) const TYPE_COUNT: usize = table::TYPES.len();

/// An effect with its duration and strength, as a potion or food gives it. A
/// `Copy` value: the `with_*` methods return a changed copy.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[doc(alias = "EffectInstance")]
pub struct Instance {
    effect: Type,
    duration: u32,
    amplifier: u8,
    visible: bool,
    ambient: bool,
    infinite: bool,
}

impl Instance {
    /// An effect instance lasting `duration` ticks, at most [`MAX_DURATION`]; the static tables
    /// make them.
    pub(crate) const fn new(
        effect: Type,
        duration: u32,
        amplifier: u8,
        visible: bool,
        ambient: bool,
    ) -> Self {
        Self {
            effect,
            duration: 0,
            amplifier,
            visible,
            ambient,
            infinite: false,
        }
        .with_duration_ticks(duration)
    }

    /// The instance a saved compound holds ([`Self::to_nbt`]); `None` for an unknown ID, a missing ID, amplifier or
    /// duration, or a negative duration other than -1 (infinite). An
    /// infinite instance lasts [`MAX_DURATION`].
    pub(crate) fn from_nbt(c: &Compound) -> Option<Self> {
        let byte = |key| match c.get(key) {
            Some(Value::Byte(b)) => Some(*b),
            _ => None,
        };
        let effect = Type::from_id(i32::from(byte(ID)?))?;
        let Some(Value::Int(saved)) = c.get(DURATION) else {
            return None;
        };
        let infinite = *saved == INFINITE_DURATION;
        let duration = if infinite {
            MAX_DURATION
        } else {
            u32::try_from(*saved).ok()?
        };
        let instance = Self::new(
            effect,
            duration,
            byte(AMPLIFIER)?,
            byte(PARTICLES).unwrap_or(1) != 0,
            byte(AMBIENT).unwrap_or(0) != 0,
        );
        Some(instance.with_infinite(infinite))
    }

    /// The same instance lasting `ticks`, at most [`MAX_DURATION`] (a longer one is cut to
    /// it).
    #[doc(alias = "EffectInstance::setDuration")]
    #[must_use]
    pub const fn with_duration_ticks(self, ticks: u32) -> Self {
        let duration = if ticks > MAX_DURATION {
            MAX_DURATION
        } else {
            ticks
        };
        Self { duration, ..self }
    }

    /// The same instance at `amplifier` (0 is level I).
    #[doc(alias = "EffectInstance::setAmplifier")]
    #[must_use]
    pub const fn with_amplifier(self, amplifier: u8) -> Self {
        Self { amplifier, ..self }
    }

    /// The same instance showing particles, or not.
    #[doc(alias = "EffectInstance::setVisible")]
    #[must_use]
    pub const fn with_visible(self, visible: bool) -> Self {
        Self { visible, ..self }
    }

    /// The same instance with faint particles, or not.
    #[doc(alias = "EffectInstance::setAmbient")]
    #[must_use]
    pub const fn with_ambient(self, ambient: bool) -> Self {
        Self { ambient, ..self }
    }

    /// The same instance never ending, or not: its duration counts down and starts again.
    #[must_use]
    pub const fn with_infinite(self, infinite: bool) -> Self {
        Self { infinite, ..self }
    }

    /// The effect type.
    #[doc(alias = "EffectInstance::getType")]
    pub fn effect(self) -> Type {
        self.effect
    }

    /// The duration in ticks.
    #[doc(alias = "EffectInstance::getDuration")]
    pub fn duration_ticks(self) -> u32 {
        self.duration
    }

    /// The amplifier: the level minus one.
    #[doc(alias = "EffectInstance::getAmplifier")]
    pub fn amplifier(self) -> u8 {
        self.amplifier
    }

    /// Whether the effect shows particles.
    #[doc(alias = "EffectInstance::isVisible")]
    pub fn is_visible(self) -> bool {
        self.visible
    }

    /// Whether the effect shows fainter particles.
    #[doc(alias = "EffectInstance::isAmbient")]
    pub fn is_ambient(self) -> bool {
        self.ambient
    }

    /// Whether the effect never ends.
    #[doc(alias = "EffectInstance::isInfinite")]
    pub fn is_infinite(self) -> bool {
        self.infinite
    }

    /// The level: the amplifier plus one.
    #[doc(alias = "EffectInstance::getEffectLevel")]
    pub fn level(self) -> u16 {
        u16::from(self.amplifier) + 1
    }

    /// Whether no time is left.
    #[doc(alias = "EffectInstance::hasExpired")]
    pub fn is_expired(self) -> bool {
        self.duration == 0
    }

    /// The particle colour: the effect type's (red, green, blue, alpha).
    #[doc(alias = "EffectInstance::getColor")]
    pub fn colour(self) -> [u8; 4] {
        self.effect.colour()
    }

    /// Whether this instance may replace `old`, an active instance of the same type: not a weaker one, nor an equally strong one that ends
    /// sooner. An infinite instance never ends, so it outlasts any finite one whatever its
    /// duration counter holds.
    #[doc(alias = "EffectCollection::canAdd")]
    pub fn can_replace(self, old: Self) -> bool {
        let ends_sooner = !self.infinite && (old.infinite || self.duration < old.duration);
        !(self.amplifier < old.amplifier || (self.amplifier == old.amplifier && ends_sooner))
    }

    /// Builds the saved form of the instance, one for players and clouds: `Id` and `Amplifier` (bytes), `Duration`
    /// (int; -1 for an infinite instance), `Ambient` and `ShowParticles` (bytes).
    pub(crate) fn to_nbt(self) -> Compound {
        // `duration` is at most `MAX_DURATION`, which is `i32::MAX`.
        let duration = if self.infinite {
            INFINITE_DURATION
        } else {
            self.duration.cast_signed()
        };
        Compound::from([
            (ID.to_owned(), Value::Byte(self.effect.id())),
            (AMPLIFIER.to_owned(), Value::Byte(self.amplifier)),
            (DURATION.to_owned(), Value::Int(duration)),
            (AMBIENT.to_owned(), Value::Byte(u8::from(self.ambient))),
            (PARTICLES.to_owned(), Value::Byte(u8::from(self.visible))),
        ])
    }
}

/// A row of the effect table.
#[derive(Debug)]
struct Data {
    id: u8,
    text: &'static str,
    /// Red, green, blue, alpha.
    colour: [u8; 4],
    bad: bool,
    instant: bool,
    default_duration: u32,
    bubbles: bool,
}

impl Data {
    const fn new(
        id: u8,
        text: &'static str,
        colour: [u8; 4],
        bad: bool,
        instant: bool,
        default_duration: u32,
        bubbles: bool,
    ) -> Self {
        Self {
            id,
            text,
            colour,
            bad,
            instant,
            default_duration,
            bubbles,
        }
    }
}

/// A row of the potion table.
#[derive(Debug)]
struct PotionData {
    id: u8,
    /// The first of the potion's effects in [`table::POTION_EFFECTS`] and their count.
    first: u16,
    count: u8,
}

impl PotionData {
    const fn new(id: u8, first: u16, count: u8) -> Self {
        Self { id, first, count }
    }
}

impl Type {
    /// Every effect type, in name order.
    pub fn all() -> &'static [Self] {
        &table::TYPES
    }

    /// The effect type with this save and network ID, or `None`.
    #[doc(alias = "EffectIdMap::fromId")]
    pub fn from_id(id: i32) -> Option<Self> {
        let id = usize::try_from(id).ok()?;
        table::TYPES_BY_ID.get(id).copied().flatten()
    }

    /// The save and network ID.
    #[doc(alias = "EffectIdMap::toId")]
    pub fn id(self) -> u8 {
        self.data().id
    }

    /// The translation key of the name, such as `potion.poison`.
    #[doc(alias = "Effect::getName")]
    pub fn translation_key(self) -> &'static str {
        self.data().text
    }

    /// The particle colour: red, green, blue, alpha.
    #[doc(alias = "Effect::getColor")]
    pub fn colour(self) -> [u8; 4] {
        self.data().colour
    }

    /// Whether the effect harms.
    #[doc(alias = "Effect::isBad")]
    pub fn is_bad(self) -> bool {
        self.data().bad
    }

    /// Whether the effect acts once instead of over time (instant health and damage).
    pub fn is_instant(self) -> bool {
        self.data().instant
    }

    /// The duration in ticks an instance has when none is given.
    #[doc(alias = "Effect::getDefaultDuration")]
    pub fn default_duration_ticks(self) -> u32 {
        self.data().default_duration
    }

    /// Whether the effect shows particles around the entity.
    #[doc(alias = "Effect::hasBubbles")]
    pub fn has_bubbles(self) -> bool {
        self.data().bubbles
    }

    /// An instance of the effect with the defaults: the [default
    /// duration](Self::default_duration_ticks), level I, particles shown, not ambient, not infinite.
    /// The [`Instance`] `with_*` methods change the rest.
    #[doc(alias = "EffectInstance::__construct")]
    pub fn instance(self) -> Instance {
        Instance::new(self, self.default_duration_ticks(), 0, true, false)
    }

    fn data(self) -> &'static Data {
        #[expect(
            clippy::indexing_slicing,
            reason = "invariant: the generated effect table has a row per effect type"
        )]
        &table::DATA[self as usize]
    }
}

impl Potion {
    /// Every potion type, in name order.
    pub fn all() -> &'static [Self] {
        &table::POTIONS
    }

    /// The potion type with this save and network ID (a potion item's meta), or `None`.
    #[doc(alias = "PotionTypeIdMap::fromId")]
    pub fn from_id(id: i32) -> Option<Self> {
        let id = usize::try_from(id).ok()?;
        table::POTIONS_BY_ID.get(id).copied().flatten()
    }

    /// The save and network ID.
    #[doc(alias = "PotionTypeIdMap::toId")]
    pub fn id(self) -> u8 {
        self.data().id
    }

    /// The English display name, such as `Night Vision`.
    #[doc(alias = "PotionType::getDisplayName")]
    pub fn display_name(self) -> &'static str {
        #[expect(
            clippy::indexing_slicing,
            reason = "invariant: the generated potion text table has a row per potion type"
        )]
        table::POTION_TEXT[self as usize]
    }

    /// The effects a drink of the potion gives.
    #[doc(alias = "PotionType::getEffects")]
    pub fn effects(self) -> &'static [Instance] {
        let data = self.data();
        let start = usize::from(data.first);
        #[expect(
            clippy::indexing_slicing,
            reason = "invariant: the generated potion rows index the effect table"
        )]
        &table::POTION_EFFECTS[start..start + usize::from(data.count)]
    }

    fn data(self) -> &'static PotionData {
        #[expect(
            clippy::indexing_slicing,
            reason = "invariant: the generated potion table has a row per potion type"
        )]
        &table::POTION_DATA[self as usize]
    }
}

/// The colour of the bubbles `effects` show: the mean of
/// the colour of each visible effect with bubbles, counted once per level; `None`
/// (transparent black) without one.
#[doc(alias = "EffectCollection::getBubbleColor")]
pub fn bubble_colour(effects: &[Instance]) -> Option<[u8; 4]> {
    mix(effects.iter().filter(|e| shows_bubbles(e)))
}

/// Whether every effect with bubbles in `effects` is ambient; false without one.
#[doc(alias = "EffectCollection::hasOnlyAmbientEffects")]
pub fn only_ambient(effects: &[Instance]) -> bool {
    let mut bubbles = effects.iter().filter(|e| shows_bubbles(e)).peekable();
    bubbles.peek().is_some() && bubbles.all(|e| e.is_ambient())
}

/// Whether the effect shows bubbles: visible, of a type with
/// bubbles.
pub(crate) fn shows_bubbles(e: &Instance) -> bool {
    e.is_visible() && e.effect.has_bubbles()
}

/// The mean colour of `effects`, each counted once per level (integer means per channel); `None` without an effect.
pub(crate) fn mix<'a>(effects: impl Iterator<Item = &'a Instance>) -> Option<[u8; 4]> {
    let mut sum = [0_u32; 4];
    let mut n = 0_u32;
    for e in effects {
        let level = u32::from(e.level());
        for (s, c) in sum.iter_mut().zip(e.colour()) {
            *s = s.saturating_add(u32::from(c).saturating_mul(level));
        }
        n = n.saturating_add(level);
    }
    let n = std::num::NonZeroU32::new(n)?;
    Some(sum.map(|s| u8::try_from(s / n).unwrap_or(u8::MAX)))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The effects whose colour is the official server's, not the dump's
    /// (`xtask/src/gen/effects.rs`).
    const OFFICIAL_COLOURED: [Type; 12] = [
        Type::FireResistance,
        Type::InstantDamage,
        Type::Invisibility,
        Type::JumpBoost,
        Type::NightVision,
        Type::Poison,
        Type::Resistance,
        Type::Slowness,
        Type::Speed,
        Type::Strength,
        Type::WaterBreathing,
        Type::Wither,
    ];

    /// The official server's colours of the effects its splash potions show (P6 `potions`,
    /// `xtask/data/p6/facts.md`); the turtle master's mix gives resistance's.
    #[test]
    fn effect_colours_are_the_ones_the_official_server_shows() {
        for (t, [r, g, b]) in [
            (Type::NightVision, [0xc2, 0xff, 0x66]),
            (Type::Invisibility, [0xf6, 0xf6, 0xf6]),
            (Type::JumpBoost, [0xfd, 0xff, 0x84]),
            (Type::FireResistance, [0xff, 0x99, 0x00]),
            (Type::Speed, [0x33, 0xeb, 0xff]),
            (Type::Slowness, [0x8b, 0xaf, 0xe0]),
            (Type::WaterBreathing, [0x98, 0xda, 0xc0]),
            (Type::InstantDamage, [0xa9, 0x65, 0x6a]),
            (Type::Poison, [0x87, 0xa3, 0x63]),
            (Type::Strength, [0xff, 0xc7, 0x00]),
            (Type::Wither, [0x73, 0x61, 0x56]),
            (Type::Resistance, [0x91, 0x46, 0xf0]),
            (Type::InstantHealth, [0xf8, 0x24, 0x23]),
            (Type::Regeneration, [0xcd, 0x5c, 0xab]),
            (Type::Weakness, [0x48, 0x4d, 0x48]),
        ] {
            assert_eq!(t.colour(), [r, g, b, 255], "{t:?}");
        }
        // Turtle master: slowness IV and resistance III, and its strong form.
        let turtle = |slowness, resistance| {
            let effects = [
                Instance::new(Type::Slowness, 20, slowness, true, false),
                Instance::new(Type::Resistance, 20, resistance, true, false),
            ];
            mix(effects.iter())
        };
        assert_eq!(turtle(3, 2), Some([0x8d, 0x82, 0xe6, 255]));
        assert_eq!(turtle(5, 3), Some([0x8d, 0x85, 0xe6, 255]));
    }

    // api: EffectIdMap::fromId, EffectIdMap::toId, PotionTypeIdMap::fromId, PotionTypeIdMap::toId
    #[test]
    fn ids_round_trip() {
        for t in Type::all() {
            assert_eq!(Type::from_id(i32::from(t.id())), Some(*t));
        }
        for p in Potion::all() {
            assert_eq!(Potion::from_id(i32::from(p.id())), Some(*p));
        }
        assert_eq!(Type::from_id(-1), None);
        assert_eq!(Type::from_id(1000), None);
        assert_eq!(Potion::from_id(1000), None);
    }

    // api: Effect, VanillaEffects, Effect::getName, Effect::getColor, Effect::isBad,
    // api: Effect::getDefaultDuration, Effect::hasBubbles, EffectInstance,
    // api: EffectInstance::getType, EffectInstance::getDuration, EffectInstance::getAmplifier,
    // api: EffectInstance::isVisible, EffectInstance::isAmbient, PotionType::getEffects,
    // api: PotionType::getDisplayName
    /// The effect and potion type values of the dump.
    #[test]
    fn effect_and_potion_data_are_the_dump_values() {
        assert_eq!(Type::all().len(), 27);
        assert_eq!(Potion::all().len(), 43);
        let poison = Type::Poison;
        assert_eq!(poison.id(), 19);
        assert!(poison.is_bad() && !poison.is_instant());
        assert_eq!(poison.translation_key(), "potion.poison");
        assert_eq!(poison.default_duration_ticks(), 600);
        assert!(Type::InstantHealth.is_instant());
        assert_eq!(Type::InstantHealth.default_duration_ticks(), 1);
        assert_eq!(Type::Absorption.colour(), [37, 82, 165, 255]);
        assert!(!Type::Darkness.has_bubbles());
        // Night vision is 3:00 (3,600 ticks), the long form 8:00.
        let [nv] = Potion::NightVision.effects() else {
            panic!("one effect");
        };
        assert_eq!(nv.effect(), Type::NightVision);
        assert_eq!((nv.duration_ticks(), nv.amplifier()), (3600, 0));
        assert!(nv.is_visible() && !nv.is_ambient());
        assert_eq!(Potion::LongNightVision.effects()[0].duration_ticks(), 9600);
        assert_eq!(Potion::StrongHealing.effects()[0].amplifier(), 1);
        assert!(Potion::Water.effects().is_empty());
        assert_eq!(Potion::Water.id(), 0);
        assert_eq!(Potion::Awkward.id(), 4);
        // Turtle master gives slowness and resistance.
        let turtle: Vec<Type> = Potion::TurtleMaster
            .effects()
            .iter()
            .map(|e| e.effect())
            .collect();
        assert_eq!(turtle, [Type::Slowness, Type::Resistance]);
        assert_eq!(Potion::NightVision.display_name(), "Night Vision");
    }

    // api: EffectInstance::__construct, EffectInstance::setDuration, EffectInstance::setAmplifier,
    // api: EffectInstance::setVisible, EffectInstance::setAmbient, EffectInstance::isInfinite,
    // api: EffectInstance::getEffectLevel, EffectInstance::hasExpired, EffectInstance::getColor
    #[test]
    fn instances_start_with_the_defaults_and_change_by_copy() {
        let speed = Type::Speed.instance();
        assert_eq!(speed.effect(), Type::Speed);
        assert_eq!(speed.duration_ticks(), Type::Speed.default_duration_ticks());
        assert_eq!((speed.amplifier(), speed.level()), (0, 1));
        assert!(speed.is_visible() && !speed.is_ambient() && !speed.is_infinite());
        assert_eq!(speed.colour(), Type::Speed.colour());
        let changed = speed
            .with_duration_ticks(u32::MAX)
            .with_amplifier(255)
            .with_visible(false)
            .with_ambient(true)
            .with_infinite(true);
        assert_eq!(changed.duration_ticks(), MAX_DURATION);
        assert_eq!((changed.amplifier(), changed.level()), (255, 256));
        assert!(!changed.is_visible() && changed.is_ambient() && changed.is_infinite());
        assert!(!speed.is_expired() && speed.with_duration_ticks(0).is_expired());
        assert_eq!(
            speed.duration_ticks(),
            Type::Speed.default_duration_ticks(),
            "a copy changed"
        );
    }

    // api: EffectCollection::canAdd, EffectCollection::getBubbleColor,
    // api: EffectCollection::hasOnlyAmbientEffects
    #[test]
    fn collections_replace_and_colour_by_the_rules() {
        let weak = Type::Speed.instance().with_duration_ticks(100);
        assert!(weak.with_amplifier(1).can_replace(weak));
        assert!(weak.with_duration_ticks(200).can_replace(weak));
        assert!(weak.can_replace(weak));
        assert!(!weak.with_duration_ticks(50).can_replace(weak));
        assert!(!weak.can_replace(weak.with_amplifier(1).with_duration_ticks(1)));
        assert_eq!(bubble_colour(&[]), None);
        assert!(!only_ambient(&[]));
        // Level II counts twice: (2 × speed + poison) / 3 per channel.
        let poison = Type::Poison.instance();
        let mixed = bubble_colour(&[weak.with_amplifier(1), poison]).unwrap();
        let (s, p) = (Type::Speed.colour(), Type::Poison.colour());
        let mean = |i: usize| u8::try_from((2 * u32::from(s[i]) + u32::from(p[i])) / 3).unwrap();
        assert_eq!(mixed, [mean(0), mean(1), mean(2), mean(3)]);
        // Hidden effects and types without bubbles do not count.
        assert_eq!(bubble_colour(&[weak, poison.with_visible(false)]), Some(s));
        let darkness = Type::Darkness.instance();
        assert_eq!(bubble_colour(&[darkness]), None);
        assert!(only_ambient(&[weak.with_ambient(true), darkness]));
        assert!(!only_ambient(&[weak.with_ambient(true), poison]));
    }

    /// An infinite instance outlasts any finite one of the same level whatever its counter holds,
    /// no finite instance replaces it, and a duration is cut at the longest the saved int holds.
    #[test]
    fn an_infinite_instance_outlasts_a_finite_one() {
        let finite = Type::Speed.instance().with_duration_ticks(9600);
        let infinite = Type::Speed
            .instance()
            .with_duration_ticks(100)
            .with_infinite(true);
        assert!(infinite.can_replace(finite));
        assert!(!finite.can_replace(infinite));
        assert!(infinite.can_replace(infinite));
        assert!(!infinite.can_replace(finite.with_amplifier(1)));
        let long = Instance::new(Type::Speed, u32::MAX, 0, true, false);
        assert_eq!(long.duration_ticks(), MAX_DURATION);
        assert_eq!(Instance::from_nbt(&long.to_nbt()), Some(long));
    }

    // api: Effect, VanillaEffects, EffectIdMap::toId, Effect::getName, Effect::getColor,
    // api: Effect::isBad, Effect::getDefaultDuration, Effect::hasBubbles, PotionTypeIdMap::toId,
    // api: PotionType::getDisplayName, PotionType::getEffects, EffectInstance::getType,
    // api: EffectInstance::getDuration, EffectInstance::getAmplifier, EffectInstance::isVisible,
    // api: EffectInstance::isAmbient
    /// Every effect and potion type has the values of the dump (`tables.json`).
    #[test]
    fn every_effect_and_potion_has_the_dump_values() {
        let dump: serde_json::Value =
            serde_json::from_str(include_str!("../xtask/data/dump/tables.json")).unwrap();
        let effects = dump["effects"].as_array().unwrap();
        assert_eq!(effects.len(), Type::all().len());
        let by_name = |name: &str| {
            let at = effects.iter().position(|e| e["name"] == name).unwrap();
            Type::all()[at]
        };
        for (t, want) in Type::all().iter().zip(effects) {
            let byte = |v: &serde_json::Value| u8::try_from(v.as_u64().unwrap()).unwrap();
            assert_eq!(u64::from(t.id()), want["id"].as_u64().unwrap(), "{t:?}");
            assert_eq!(t.translation_key(), want["text"].as_str().unwrap(), "{t:?}");
            // The official server's colours replace the dump's for the effects its potions show
            // (`effect_colours_are_the_ones_the_official_server_shows`).
            let c = &want["colour"];
            if !OFFICIAL_COLOURED.contains(t) {
                assert_eq!(
                    t.colour(),
                    [byte(&c["r"]), byte(&c["g"]), byte(&c["b"]), byte(&c["a"])]
                );
            }
            assert_eq!(Some(t.is_bad()), want["bad"].as_bool(), "{t:?}");
            assert_eq!(Some(t.is_instant()), want["instant"].as_bool(), "{t:?}");
            assert_eq!(
                u64::from(t.default_duration_ticks()),
                want["default_duration"].as_u64().unwrap()
            );
            assert_eq!(Some(t.has_bubbles()), want["bubbles"].as_bool(), "{t:?}");
        }
        let potions = dump["potions"].as_array().unwrap();
        assert_eq!(potions.len(), Potion::all().len());
        for (p, want) in Potion::all().iter().zip(potions) {
            assert_eq!(u64::from(p.id()), want["id"].as_u64().unwrap(), "{p:?}");
            assert_eq!(p.display_name(), want["text"].as_str().unwrap(), "{p:?}");
            let wanted = want["effects"].as_array().unwrap();
            assert_eq!(p.effects().len(), wanted.len(), "{p:?}");
            for (e, w) in p.effects().iter().zip(wanted) {
                assert_eq!(e.effect(), by_name(w["effect"].as_str().unwrap()));
                assert_eq!(
                    u64::from(e.duration_ticks()),
                    w["duration"].as_u64().unwrap()
                );
                assert_eq!(u64::from(e.amplifier()), w["amplifier"].as_u64().unwrap());
                assert_eq!(Some(e.is_visible()), w["visible"].as_bool());
                assert_eq!(Some(e.is_ambient()), w["ambient"].as_bool());
            }
        }
    }
}
